function validateWindows(n){
 const errors=[],counts={records:0,checkpoints:0,segments:0,bucketCells:0,ordinalRows:0,scalarDifferences:0,bucketDifferences:0},q=n.queryCounts,d=q.rpcActions.queryDiagnostics;
 const eq=(a,b,label)=>{if(a!==b)errors.push({label,actual:a,expected:b});},sum=x=>Object.values(x).reduce((a,b)=>a+b,0),scalars=["queryCalls","pgProtocolReceiveBytes","pgProtocolSendBytes","closedConnections","unknownReadings"],bucketNames=["queryOperations","unattributedSources"];
 const inventory=r=>{counts.records++;counts.bucketCells+=Object.keys(r.queryOperations).length+Object.keys(r.unattributedSources).length;eq(sum(r.queryOperations),r.queryCalls,"operation sum");eq(sum(r.unattributedSources),r.queryOperations.unattributed,"source sum");eq(Object.keys(r.queryOperations).length,17,"operation keys");eq(Object.keys(r.unattributedSources).length,78,"source keys");};
 const difference=(out,a,b,label)=>{for(const k of scalars){counts.scalarDifferences++;eq(out[k],b[k]-a[k],label+"."+k);}for(const group of bucketNames){eq(JSON.stringify(Object.keys(out[group]).sort()),JSON.stringify(Object.keys(a[group]).sort()),label+" keyset before "+group);eq(JSON.stringify(Object.keys(out[group]).sort()),JSON.stringify(Object.keys(b[group]).sort()),label+" keyset after "+group);for(const[k,v]of Object.entries(out[group])){counts.bucketDifferences++;eq(v,b[group][k]-a[group][k],label+"."+group+"."+k);}}eq(out.startedAt,new Date(a.endedAt).toISOString(),label+" start");eq(out.finishedAt,new Date(b.endedAt).toISOString(),label+" end");eq(out.durationMs,b.endedAt-a.endedAt,label+" duration");};
 const rowProject=(rows,total,label)=>{const ops=Object.fromEntries(Object.keys(total.queryOperations).map(k=>[k,0])),sources=Object.fromEntries(Object.keys(total.unattributedSources).map(k=>[k,0]));for(const row of rows){const key=d.scopeKeys[row[3]];if(key in sources){sources[key]++;ops.unattributed++;}else if(key in ops)ops[key]++;else errors.push({label:label+" missing scope",scope:row[3]});}for(const[k,v]of Object.entries(ops))eq(v,total.queryOperations[k],label+".ops."+k);for(const[k,v]of Object.entries(sources))eq(v,total.unattributedSources[k],label+".sources."+k);};
 const windows={};
 for(const[name,w]of Object.entries(q.windows)){
  const ds=d.windows[name],cp=w.checkpoints,sg=w.segments;eq(w.status,"complete",name+" closed");eq(cp.length,sg.length+1,name+" checkpoint count");if(name.startsWith("startup"))eq(w.pair,1,name+" FIRST pair");
  for(const c of cp){counts.checkpoints++;inventory(c.snapshot);eq(c.snapshot.pid,q.source.pid,name+" primary PID");}
  for(let i=0;i<sg.length;i++){counts.segments++;inventory(sg[i]);difference(sg[i],cp[i].snapshot,cp[i+1].snapshot,name+"."+sg[i].phase);}
  inventory(w.total);difference(w.total,cp[0].snapshot,cp.at(-1).snapshot,name+".total");for(const k of scalars)eq(sg.reduce((s,g)=>s+g[k],0),w.total[k],name+" segment scalar "+k);for(const group of bucketNames)for(const[k,v]of Object.entries(w.total[group]))eq(sg.reduce((s,g)=>s+g[group][k],0),v,name+" segment bucket "+group+"."+k);
  eq(ds.fromQueryCalls,cp[0].snapshot.queryCalls,name+" ordinal start");eq(ds.toQueryCalls,cp.at(-1).snapshot.queryCalls,name+" ordinal end");eq(ds.expectedQueries,w.total.queryCalls,name+" expected");eq(ds.capturedQueries,ds.queries.length,name+" captured");eq(ds.uncapturedQueries,0,name+" uncaptured");eq(ds.queries.length,w.total.queryCalls,name+" total ordinal count");
  const partition={bothKnown:0,contextUnknownOnly:0,statementUnknownOnly:0,bothUnknown:0};let uc=0,us=0;
  for(let i=0;i<ds.queries.length;i++){const row=ds.queries[i];counts.ordinalRows++;eq(row.length,4,name+" columns");eq(row[0],ds.fromQueryCalls+i+1,name+" contiguous");const c=d.contexts[row[1]],s=d.statements[row[2]];if(!c||!s){errors.push({label:name+" invalid reference",row});continue;}const a=c.status==="unknown",b=s.status==="unknown";uc+=+a;us+=+b;partition[a?(b?"bothUnknown":"contextUnknownOnly"):(b?"statementUnknownOnly":"bothKnown")]++;}
  eq(uc,ds.unknownContextQueries,name+" unknown context");eq(us,ds.unknownStatementQueries,name+" unknown statement");rowProject(ds.queries,w.total,name+".ordinal-total");
  const segments=[];
  for(let i=0;i<sg.length;i++){const spec=ds.segments[i],before=cp[i].snapshot.queryCalls,after=cp[i+1].snapshot.queryCalls;eq(spec.phase,sg[i].phase,name+" segment phase");eq(spec.fromQueryCalls,before,name+" segment from");eq(spec.toQueryCalls,after,name+" segment to");const rows=ds.queries.filter(r=>r[0]>before&&r[0]<=after);eq(rows.length,sg[i].queryCalls,name+" segment row count");rowProject(rows,sg[i],name+"."+sg[i].phase);segments.push({phase:sg[i].phase,fromQueryCalls:before,toQueryCalls:after,count:rows.length});}
  const rpc={};for(const[k,col]of Object.entries({physical:q.rpcActions.windows,logical:q.rpcActions.logical.windows})){const rs=col[name];eq(rs.startedAt,w.total.startedAt,name+" "+k+" start");eq(rs.finishedAt,w.total.finishedAt,name+" "+k+" end");rpc[k]=Object.fromEntries(["startedInWindow","completedInWindow","crossesStart","crossesEnd","completionNotObserved","completionWithoutStart"].map(key=>[key,rs.actions.reduce((n,a)=>n+a[key],0)]));}
  windows[name]={queryCalls:w.total.queryCalls,receiveBytes:w.total.pgProtocolReceiveBytes,sendBytes:w.total.pgProtocolSendBytes,durationMs:w.total.durationMs,ordinalFrom:ds.fromQueryCalls,ordinalTo:ds.toQueryCalls,segments,unknownContext:uc,unknownStatement:us,unknownPartition:partition,rpc,diagnosticStatus:ds.status,diagnosticReasons:ds.reasons};
 }
 eq(d.capture.droppedQueries,0,"capture dropped");eq(d.capture.overflow,false,"capture overflow");eq(d.receipts.unmatchedQueryContexts,0,"unmatched contexts");eq(d.receipts.unpairedInvocations,0,"unpaired invocations");eq(d.receipts.conflictingInvocations,0,"conflicting invocations");
 return {counts,errors,windows,scope:q.scope,background:q.background,boundary:q.boundary,exclusions:q.exclusions,diagnosticBoundary:d.boundary,capture:d.capture,receiptStatus:d.receipts.status,verdicts:{fullNativeAtMostWeb:q.windows.nativeLogin.total.queryCalls<=q.windows.webLogin.total.queryCalls,firstNativeAtMostHosted:q.windows["startup-bundled"].total.queryCalls<=q.windows["startup-hosted"].total.queryCalls}};
}

