function project(n){
 const q=n.queryCounts,d=q.rpcActions.queryDiagnostics,receipts=new Map(d.receipts.invocations.map(r=>[r.invocationId,r]));
 const add=(obj,k,v=1)=>{obj[k]=(obj[k]??0)+v;}; const output={revision:n.revision,source:q.source,apiStartedAt:new Date(d.source.startedAt).toISOString(),windows:{}};
 for(const[name,w]of Object.entries(q.windows)){
  const ds=d.windows[name],contexts={},statements={},scopes={},invocations=new Map(),unknownRows=[];
  for(const row of ds.queries){
   const[ordinal,ci,si,ki]=row,c=d.contexts[ci],s=d.statements[si],scope=d.scopeKeys[ki],sk=s.status==="unknown"?"unknown":s.normalizedStructureId,key=c.status==="unknown"?"unknown":JSON.stringify([c.route,c.method,c.rpcAction]);
   add(statements,sk);add(scopes,scope);
   let group=contexts[key];if(!group)group=contexts[key]={key,status:c.status,route:c.route??null,method:c.method??null,rpcAction:c.rpcAction??null,queryCalls:0,statementCounts:{},scopeCounts:{},invocationIds:[],unknownStatementQueries:0};group.queryCalls++;add(group.statementCounts,sk);add(group.scopeCounts,scope);group.unknownStatementQueries+=+(s.status==="unknown");
   if(c.status==="unknown"){unknownRows.push({ordinal,statement:sk,scope});continue;}
   if(!group.invocationIds.includes(c.invocationId))group.invocationIds.push(c.invocationId);
   let iv=invocations.get(c.invocationId);if(!iv){iv={context:{...c},receipt:receipts.get(c.invocationId)??null,rows:[],statementCounts:{},scopeCounts:{}};invocations.set(c.invocationId,iv);}
   iv.rows.push({ordinal,statement:sk,scope,contextIndex:ci,statementIndex:si,scopeIndex:ki});add(iv.statementCounts,sk);add(iv.scopeCounts,scope);
  }
  const start=Date.parse(w.total.startedAt),end=Date.parse(w.total.finishedAt),crossingReceipts=d.receipts.invocations.filter(r=>{const s=Date.parse(r.startedAt),e=Date.parse(r.completedAt);return(s<start&&e>=start)||(s<end&&e>=end);}).map(r=>({...r,crossesStart:Date.parse(r.startedAt)<start&&Date.parse(r.completedAt)>=start,crossesEnd:Date.parse(r.startedAt)<end&&Date.parse(r.completedAt)>=end,completionAfterEndMs:Math.max(0,Date.parse(r.completedAt)-end)}));
  output.windows[name]={total:w.total,segments:w.segments,checkpoints:w.checkpoints.map(x=>({phase:x.phase,queryCalls:x.snapshot.queryCalls,endedAt:x.snapshot.endedAt})),ordinalFrom:ds.fromQueryCalls,ordinalTo:ds.toQueryCalls,contexts:Object.values(contexts).sort((a,b)=>a.key.localeCompare(b.key)),statementCounts:statements,scopeCounts:scopes,invocations:[...invocations.values()].sort((a,b)=>a.rows[0].ordinal-b.rows[0].ordinal),unknownRows,physicalRPC:q.rpcActions.windows[name],logicalRPC:q.rpcActions.logical.windows[name],crossingReceipts,apiAgeAtStartMs:start-d.source.startedAt,diagnostic:{status:ds.status,reasons:ds.reasons,expectedQueries:ds.expectedQueries,capturedQueries:ds.capturedQueries,uncapturedQueries:ds.uncapturedQueries,unknownContextQueries:ds.unknownContextQueries,unknownStatementQueries:ds.unknownStatementQueries}};
 }
 output.statementDefinitions=Object.fromEntries(d.statements.map(s=>[s.status==="unknown"?"unknown":s.normalizedStructureId,s]));return output;
}

reproduction.additionalComparisonFunction:
function auditDeltaExtras(oldProjection,newProjection){
 const diff=(a,b)=>[...new Set([...Object.keys(a),...Object.keys(b)])].sort().filter(k=>(a[k]||0)!==(b[k]||0)).map(key=>({key,old:a[key]||0,new:b[key]||0,delta:(b[key]||0)-(a[key]||0)}));
 const count=(xs,key)=>{const o={};for(const x of xs){const k=key(x);o[k]=(o[k]||0)+1;}return o;};
 const flat=w=>[
  ...w.invocations.flatMap(i=>i.rows.map(r=>({...r,contextKey:JSON.stringify([i.context.route,i.context.method,i.context.rpcAction??null]),invocationId:i.context.invocationId,httpInvocationId:i.context.httpInvocationId}))),
  ...w.unknownRows.map(r=>({...r,contextKey:"unknown",invocationId:null,httpInvocationId:null}))
 ].sort((a,b)=>a.ordinal-b.ordinal);
 const cell=r=>JSON.stringify([r.contextKey,r.statement,r.scope]);
 const oldW=oldProjection.windows.webLogin,newW=newProjection.windows.webLogin,oldRows=flat(oldW),newRows=flat(newW),prefix=oldRows.slice(0,newRows.length),tail=oldRows.slice(newRows.length);
 const contexts=w=>Object.fromEntries(w.contexts.map(c=>[c.key,c.queryCalls]));
 const invProfile=w=>w.invocations.map(i=>({
  key:JSON.stringify([i.context.route,i.context.method,i.context.rpcAction??null]),invocationId:i.context.invocationId,httpInvocationId:i.context.httpInvocationId,
  queryCalls:i.rows.length,firstOrdinal:i.rows[0]?.ordinal??null,lastOrdinal:i.rows[i.rows.length-1]?.ordinal??null,
  startedAt:i.receipt?.startedAt??null,completedAt:i.receipt?.completedAt??null,httpStatus:i.receipt?.httpStatus??null,
  startRelativeMs:i.receipt?.startedAt?Date.parse(i.receipt.startedAt)-Date.parse(w.total.startedAt):null,
  endRelativeMs:i.receipt?.completedAt?Date.parse(i.receipt.completedAt)-Date.parse(w.total.startedAt):null,
  statementCounts:i.statementCounts,scopeCounts:i.scopeCounts
 }));
 const perWindow={};
 for(const name of Object.keys(oldProjection.windows)){
  const a=oldProjection.windows[name],b=newProjection.windows[name];
  const ap=invProfile(a),bp=invProfile(b);const groups={};
  for(const key of new Set([...ap.map(i=>i.key),...bp.map(i=>i.key)])){
   const ai=ap.filter(i=>i.key===key),bi=bp.filter(i=>i.key===key);
   groups[key]={old:ai,new:bi,pairs:[...Array(Math.min(ai.length,bi.length)).keys()].map(i=>({ordinalCall:i+1,oldInvocation:ai[i].invocationId,newInvocation:bi[i].invocationId,queryDelta:bi[i].queryCalls-ai[i].queryCalls,statementDeltas:diff(ai[i].statementCounts,bi[i].statementCounts),scopeDeltas:diff(ai[i].scopeCounts,bi[i].scopeCounts)}))};
  }
  const segmentDiffs=a.segments.map((s,i)=>{const t=b.segments[i];return {oldPhase:s.phase,newPhase:t.phase,oldQueries:s.queryCalls,newQueries:t.queryCalls,delta:t.queryCalls-s.queryCalls,oldDurationMs:s.durationMs,newDurationMs:t.durationMs,operationDeltas:diff(s.queryOperations,t.queryOperations),unattributedSourceDeltas:diff(s.unattributedSources,t.unattributedSources)};});
  perWindow[name]={segmentDiffs,contextDeltas:diff(contexts(a),contexts(b)),statementDeltas:diff(a.statementCounts,b.statementCounts),scopeDeltas:diff(a.scopeCounts,b.scopeCounts),perInvocationGroups:groups,
   oldUnknownRows:a.unknownRows,newUnknownRows:b.unknownRows,
   unknownCompositeDeltas:diff(count(a.unknownRows,r=>JSON.stringify([r.statement,r.scope])),count(b.unknownRows,r=>JSON.stringify([r.statement,r.scope])))};
 }
 return {webPrefixReconciliation:{oldWindowQueries:oldRows.length,newWindowQueries:newRows.length,prefixCount:prefix.length,tailCount:tail.length,prefixOrdinals:[prefix[0].ordinal,prefix[prefix.length-1].ordinal],tailOrdinals:[tail[0].ordinal,tail[tail.length-1].ordinal],compositeKey:["originalContextRouteMethodActionOrUnknown","statementStructureOrUnknown","originalScope"],newVersusOldPrefixCompositeDifferences:diff(count(prefix,cell),count(newRows,cell)),tailContextCounts:count(tail,r=>r.contextKey),tailStatementCounts:count(tail,r=>r.statement),tailScopeCounts:count(tail,r=>r.scope),tailRows:tail},perWindow};
}
